-- Import delivered coastal development cases as reviewable drafts.
-- Preserve full source rows, ambiguous dates, discrepancies and all geometry.
-- Re-execution skips source IDs, preserving subsequent manual edits.
CREATE UNIQUE INDEX IF NOT EXISTS development_source_feature_unique
 ON public_content ((source_snapshot->>'source_feature_id'))
 WHERE kind='development' AND source_snapshot ? 'source_feature_id';
DO $import$
DECLARE item jsonb; cid bigint;
BEGIN
 PERFORM pg_advisory_xact_lock(76104,1);
 FOR item IN SELECT value FROM jsonb_array_elements($development_import$[{"data":{"title":"外澳觀光旅館","summary":"近年該林姓業者向觀光局提出「外澳觀光旅館」開發案，意欲租用原有地（私人招待所兼博物館）南邊的國有地0.72公頃，連同原本的建築、庭園1.02公頃，擴張開發新的觀光飯店，新舊開發面積達到1.74公頃。然而該國有地為景觀保護區，觀光局表示，必須先經由都市計畫變更為旅館區，才可辦理承租。目前該計畫林姓業者委託山點水股份有限公司進行規劃、設計及提出申請。該開發案範圍阻擋觀海視線、開發將危及當地海洋生態，影響漁民生計、該業主始終不曾與地方居民有所往來，未來飯店開張要結合在地特色發展觀光令人質疑等","county":"宜蘭縣","authority":"","status":"尚未通過環評","source_url":"https://docs.google.com/spreadsheets/d/1aESMD2YyrOcKd0f3XAaOcNhAz_ENo3vd/edit?gid=2144450313#gid=2144450313&range=A1","geometry":{"type":"Point","coordinates":[121.843136,24.878133]},"sort_order":1,"timeline":[{"title":"榮梓博物館，是位於臺灣宜蘭縣頭城鎮外澳、林昭文擁有的私人招待所兼博物館，以阿拉伯風格建造，是當地著名的景點。地址是頭城鎮濱海路二段328號。約2005年時原先別","description":"榮梓博物館，是位於臺灣宜蘭縣頭城鎮外澳、林昭文擁有的私人招待所兼博物館，以阿拉伯風格建造，是當地著名的景點。地址是頭城鎮濱海路二段328號。約2005年時原先別墅拆除，2006年再成立","date":"2006","date_precision":"year","source_url":"https://docs.google.com/spreadsheets/d/1aESMD2YyrOcKd0f3XAaOcNhAz_ENo3vd/edit?gid=2144450313#gid=2144450313&range=A1","sort_order":1,"status":"","is_published":false},{"title":"因建築吸引遊客眼光，林家在2010年開始計畫發成觀光旅館，欲併購鄰近土地，把公有海灘劃入承租，以及興建23棟一晚收費2萬3千元到3萬元的觀光旅館。屆時若旅館啟用","description":"因建築吸引遊客眼光，林家在2010年開始計畫發成觀光旅館，欲併購鄰近土地，把公有海灘劃入承租，以及興建23棟一晚收費2萬3千元到3萬元的觀光旅館。屆時若旅館啟用，博物館就會開放讓飯店遊客參觀。\n來源維基百科：https://zh.wikipedia.org/zh-tw/%E6%A6%AE%E6%A2%93%E5%8D%9A%E7%89%A9%E9%A4%A8","date":"2010","date_precision":"year","source_url":"https://zh.wikipedia.org/zh-tw/%E6%A6%AE%E6%A2%93%E5%8D%9A%E7%89%A9%E9%A4%A8","sort_order":2,"status":"","is_published":false},{"title":"外澳土地變更案內政部都委會第一次審查","description":"外澳土地變更案內政部都委會第一次審查\n守護外澳海岸線/我們的島：https://ourisland.pts.org.tw/content/1016","date":"2013-11-11","date_precision":"day","source_url":"https://ourisland.pts.org.tw/content/1016","sort_order":3,"status":"","is_published":false},{"title":"宜蘭外澳海岸的保護區將變更為旅館區，營建署昨（11日）召開審查會議，外澳居民組成的「守護外澳海岸」、「外澳社區發展協會」、宜蘭青年、學生及民間團體，在場外召開記","description":"宜蘭外澳海岸的保護區將變更為旅館區，營建署昨（11日）召開審查會議，外澳居民組成的「守護外澳海岸」、「外澳社區發展協會」、宜蘭青年、學生及民間團體，在場外召開記者會表達堅決抵抗的立場。\n外澳保護區變旅館區 居民抗議：https://e-info.org.tw/node/94933","date":"2013-11-12","date_precision":"day","source_url":"https://e-info.org.tw/node/94933","sort_order":4,"status":"","is_published":false},{"title":"宜蘭頭城外澳海岸，之前就傳出有飯店業者打算將國有地申請變更為旅館用地，再承租興建旅館營利，但當時申請失敗，但最近業者卻悄悄開工，還圍起石牆、砍光原有樹木，涉嫌侵","description":"宜蘭頭城外澳海岸，之前就傳出有飯店業者打算將國有地申請變更為旅館用地，再承租興建旅館營利，但當時申請失敗，但最近業者卻悄悄開工，還圍起石牆、砍光原有樹木，涉嫌侵占國有地。\n「小白宮」築石牆砍樹　強佔外澳國有地：https://news.tvbs.com.tw/politics/748367?fbclid=IwAR3GQyWjOl_0NajHIbFOpeY1ux5gIJLR-qWGtyrvW6G8IcXrECoSwB5i2e0","date":"2017-07-20","date_precision":"day","source_url":"https://news.tvbs.com.tw/politics/748367?fbclid=IwAR3GQyWjOl_0NajHIbFOpeY1ux5gIJLR-qWGtyrvW6G8IcXrECoSwB5i2e0","sort_order":5,"status":"","is_published":false},{"title":"位於宜蘭外澳的「阿拉伯宮」榮梓博物館，正求售中!這座由「阿拉伯王」之稱林昭文斥資上億元，興建的博物館，曾招待前總統李登輝、前副總統連戰、台塑集團創辦人王永慶等人","description":"位於宜蘭外澳的「阿拉伯宮」榮梓博物館，正求售中!這座由「阿拉伯王」之稱林昭文斥資上億元，興建的博物館，曾招待前總統李登輝、前副總統連戰、台塑集團創辦人王永慶等人，現因林昭文身體每況愈下，妻子林楊桂蓮委託仲介，以33 億元求售，正待有緣人中。\n總統、巨富都來過 神祕「阿拉伯宮」不得不賣有原因：https://www.chinatimes.com/realtimenews/20180815001553-260405?chdtv","date":"2018-08-15","date_precision":"day","source_url":"https://www.chinatimes.com/realtimenews/20180815001553-260405?chdtv","sort_order":6,"status":"","is_published":false},{"title":"阿拉伯宮求售近1年，外界盛傳最近有外縣市建商以21億元高價，順利入主「阿拉伯宮」，入手價與去年開價相比，相當於折了12億餘元。對此，余文雄表示，目前八字還沒一撇","description":"阿拉伯宮求售近1年，外界盛傳最近有外縣市建商以21億元高價，順利入主「阿拉伯宮」，入手價與去年開價相比，相當於折了12億餘元。對此，余文雄表示，目前八字還沒一撇，他沒聽過相關成交訊息，外界傳言是空穴來風。\n宜蘭外澳「阿拉伯宮」傳以21億易主：https://ec.ltn.com.tw/article/breakingnews/2845913","date":"2019-07-08","date_precision":"day","source_url":"https://ec.ltn.com.tw/article/breakingnews/2845913","sort_order":7,"status":"","is_published":false}],"media":[],"area_m2":17400.0,"investment_ntd":600000000.0},"snapshot":{"source_feature_id":"mymaps-01b148b74926","source_format":"development-handoff-2026-11-04","source_sha256":{"development_cases.csv":"2054df0f253078988062ec83d8d97c127c9c28bf718e47ebb943afef8276859d","development_case_timeline.csv":"38f579878e66decdb65c6bc6d4f9eec78b2b0e10