ent_key":"timeline-77f8848d49ef0ae4","source_feature_id":"mymaps-c54b1d18d459","source_order":"3","event_date_raw":"2016.06","event_date_start":"2016-06-01","event_date_end":"2016-06-30","date_precision":"month","phase_label":"","event_text":"通過環評大會審查，現進行水保工程。","note_text":"","source_sheet_name":"10棕櫚濱海渡假村","source_sheet_gid":"1679878870","source_row":"9"},{"event_key":"timeline-6b35a363da0bbb29","source_feature_id":"mymaps-c54b1d18d459","source_order":"4","event_date_raw":"2016.07.27","event_date_start":"2016-07-27","event_date_end":"2016-07-27","date_precision":"day","phase_label":"","event_text":"通過環現差","note_text":"","source_sheet_name":"10棕櫚濱海渡假村","source_sheet_gid":"1679878870","source_row":"10"},{"event_key":"timeline-af7edf12fdb8c7f1","source_feature_id":"mymaps-c54b1d18d459","source_order":"5","event_date_raw":"2016.12.23","event_date_start":"2016-12-23","event_date_end":"2016-12-23","date_precision":"day","phase_label":"","event_text":"環評補考「修正後通過」，引發民間譁然，陳情行政院長林全，林全則裁示，在獲得「當地部落知情同意」前無法開發","note_text":"","source_sheet_name":"10棕櫚濱海渡假村","source_sheet_gid":"1679878870","source_row":"11"}],"development_case_timeline_source.csv":[{"timeline_source_key":"timeline-source-fbc9536e388ae30f","event_key":"timeline-6019053c52a0ed31","source_feature_id":"mymaps-c54b1d18d459","sort_order":"1","source_label":"杉原又見未環評先動工 棕櫚渡假村補件再審\n杉原棕櫚濱海渡假村開發 仍有諸多未解的疑慮","source_url":"https://e-info.org.tw/node/86229","source_sheet_name":"10棕櫚濱海渡假村","source_sheet_gid":"1679878870","source_row":"8"},{"timeline_source_key":"timeline-source-7e7ee215e164af04","event_key":"timeline-af7edf12fdb8c7f1","source_feature_id":"mymaps-c54b1d18d459","sort_order":"2","source_label":"杉原棕櫚十度環差過關 林全緩頰暫不開發","source_url":"https://e-info.org.tw/node/202023","source_sheet_name":"10棕櫚濱海渡假村","source_sheet_gid":"1679878870","source_row":"11"}],"development_case_media.csv":[],"development_case_source.csv":[],"development_case_discrepancy.csv":[]}}},{"data":{"title":"都蘭灣黃金海休閒渡假村","summary":"黃金海渡假村2000年就通過環評，但超過三年未動工，依法在2006年提交第一次「環境現況差異分析及對策檢討報告」（環現差），歷經數次初審補件後，最終在2018年因未提出廢水回收及排放影響的因應對策，以及對於海域珊瑚與魚類及陸域的生態調查不足等原因，遭到環保署退回目的事業主管機關交通部觀光局。\n\n2020年黃金海公司再送第二次環現差審查，環評重點也持續圍繞在開發規模過大、生態及遺址調查資料不足及原住民傳統領域等，總共歷經兩年、開發單位四次補件，都無法獲得環委同意，甚至遭致「越改越離譜」、「浪費多次審查時間」等批評，昨日環評大會也決議再次退回觀光局。\n\n觀光局透過書面表示，黃金海通過環評已超過20年，市場現況變化大，且業者資金需求及籌措方式已無法依原計畫辦理。此次退回後，將依「觀光遊樂業管理規則」第15-1條規定，開發單位須在一年內重新提出申請變更興辦事業計畫，屆期若未提出申請變更，此案過去的籌設核准就將失效。也就是說，籌設核准一旦失效後，黃金海開發案就將正式走入歷史，無再審可能。\n待核對（area）：詳細頁 11.3208公頃；總表 11.3公頃。","county":"台東縣","authority":"交通部觀光局","status":"通過環評尚未開發（第二次環現差未通過）","source_url":"https://docs.google.com/spreadsheets/d/1aESMD2YyrOcKd0f3XAaOcNhAz_ENo3vd/edit?gid=877972351#gid=877972351&range=A1","geometry":{"type":"Point","coordinates":[121.183827,22.829922]},"sort_order":11,"timeline":[{"title":"通過環評，但六年內都遲遲不動工。","description":"通過環評，但六年內都遲遲不動工。","date":"2000-03","date_precision":"month","source_url":"https://docs.google.com/spreadsheets/d/1aESMD2YyrOcKd0f3XAaOcNhAz_ENo3vd/edit?gid=877972351#gid=877972351&range=A1","sort_order":1,"status":"","is_published":false},{"title":"[第一案] 因本案超過三年未動工，依法應進行第一次「環境現況差異分析(環現差)」程序， 觀光局於 2006 年將資料送至環保署成案(案號 0950445A)。","description":"第1次 專案小組一審，決議:補件再審。","date":"2006-11","date_precision":"month","source_url":"https://docs.google.com/spreadsheets/d/1aESMD2YyrOcKd0f3XAaOcNhAz_ENo3vd/edit?gid=877972351#gid=877972351&range=A1","sort_order":2,"status":"[第一案] 因本案超過三年未動工，依法應進行第一次「環境現況差異分析(環現差)」程序， 觀光局於 2006 年將資料送至環保署成案(案號 0950445A)。","is_published":false},{"title":"[第一案] 因本案超過三年未動工，依法應進行第一次「環境現況差異分析(環現差)」程序， 觀光局於 2006 年將資料送至環保署成案(案號 0950445A)。","description":"第2次 專案小組二審，決議:建議通過，送大會確認。","date":"2007-05","date_precision":"month","source_url":"https://docs.google.com/spreadsheets/d/1aESMD2YyrOcKd0f3XAaOcNhAz_ENo3vd/edit?gid=877972351#gid=877972351&range=A1","sort_order":3,"status":"[第一案] 因本案超過三年未動工，依法應進行第一次「環境現況差異分析(環現差)」程序， 觀光局於 2006 年將資料送至環保署成案(案號 0950445A)。","is_published":false},{"title":"[第一案] 因本案超過三年未動工，依法應進行第一次「環境現況差異分析(環現差)」程序， 觀光局於 2006 年將資料送至環保署成案(案號 0950445A)。","description":